package com.intakeflow.api;
import org.springframework.dao.OptimisticLockingFailureException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ApiException.class) ProblemDetail api(ApiException e){var p=ProblemDetail.forStatusAndDetail(e.getStatus(),e.getMessage());p.setTitle("Request could not be completed");return p;}@ExceptionHandler(MethodArgumentNotValidException.class) ProblemDetail validation(MethodArgumentNotValidException e){var p=ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,"Please correct the highlighted information.");p.setTitle("Validation failed");p.setProperty("errors",e.getBindingResult().getFieldErrors().stream().collect(java.util.stream.Collectors.toMap(x->x.getField(),x->x.getDefaultMessage()==null?"Invalid value":x.getDefaultMessage(),(a,b)->a)));return p;}@ExceptionHandler(OptimisticLockingFailureException.class) ProblemDetail conflict(){return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT,"This request changed while you were viewing it. Refresh and try again.");}}
